&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 15px;"&gt;
&lt;p&gt;&lt;span style="font-size: 1.2em;"&gt;🧰&lt;/span&gt; &lt;span style="text-transform: uppercase;    font-weight: 600; font-size: 1.4em;"&gt;Tools, Code &amp;amp; Resources&lt;/span&gt;&lt;/p&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;

&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 18px;"&gt;
  &lt;a href="https://frontendfoc.us/link/189459/rss" style=" color: #D94306;"&gt;&lt;img src="https://res.cloudinary.com/cpress/image/upload/w_1280,e_sharpen:60,q_auto/v1787659751/avgl98bbwrisvu9vul3w.png" width="140" height="" style="padding-top: 12px; padding-left: 12px;     line-height: 100%; "&gt;&lt;/a&gt;
  &lt;p&gt;&lt;span style="font-weight: 400 !important; font-size: 1.3em !important; color: #000;"&gt;&lt;a href="https://frontendfoc.us/link/189459/rss" title="a-dev.github.io" style=" color: #D94306;"&gt;CSS &lt;code&gt;corner-shape&lt;/code&gt; Generator: Squircles With a Fallback&lt;/a&gt;&lt;/span&gt; — A browser-based tool where you can adjust sliders to get the desired look and then copy the CSS. There's &lt;a href="https://frontendfoc.us/link/189460/rss" style=" color: #D94306;"&gt;a related blog post here&lt;/a&gt;.&lt;/p&gt;
  &lt;p&gt;a-dev &lt;/p&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;

&lt;table border=0 cellpadding=0 cellspacing=0 border=0 cellpadding=0 cellspacing=0&gt;&lt;tr&gt;&lt;td style="font-size: 15px; line-height: 1.48em; padding: 0px 18px;"&gt;

